///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalChangePage
 * @description Digital Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalChangePage",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalChangePageReq",
        target: "dlt_readDataFileVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

