///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/digital/FileDownload.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name digitalChangePage
 * @description digital Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalChangePage = async function (tab) {
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (tab === 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                return;
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
};

