/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    const elem = $c.util.getComponent('digitalListForm').elements;
    const str = '';
    for (let i = 0; i < elem.length; i++) {
        if (elem[i].type !== 'hidden') {
            if (elem[i].value === '') {
                await $c.win.alert(elem[i].id + " 값을 입력해주세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            }
        }
    }
    return true;
};

